package service
import("sort";"testing";"time";"ballast-watch/internal/model";"ballast-watch/internal/store")
func TestBug22_AlertListNoAlias(t *testing.T){svc:=ballastTestServices(t);alerts:=store.NewComplianceComplianceAlertStore(svc.Store);for i,l:=range []string{model.ComplianceAlertWarn,model.ComplianceAlertAlarm}{if err:=alerts.Create(ballastCtx(),&model.ComplianceAlert{RuleID:int64(i+1),BallastTankID:1,SamplingPointID:1,Level:l,Status:model.ComplianceAlertOpen,OpenedAt:time.Now().Add(time.Duration(i)*time.Minute)});err!=nil{t.Fatal(err)}};first,_:=alerts.List(ballastCtx(),model.ComplianceComplianceAlertInput{Limit:10});sort.Slice(first,func(i,j int)bool{return first[i].Level>first[j].Level});second,_:=alerts.List(ballastCtx(),model.ComplianceComplianceAlertInput{Limit:10});if second[0].Level!=model.ComplianceAlertAlarm{t.Fatal("alert list was polluted by caller sort")}}
